# Official brand assets and default blueprint background for ICEBADGER / CRIMSON PAW.
# ────────────────────────────────────────────────────────────────────────────

BRAND_LOGOS_B64 = {
    'Adobe': 'data:image/png;base64,',
    'Adobe Sign': 'data:image/png;base64,',
    'DocuSign': 'data:image/png;base64,',
    'Dropbox': 'data:image/png;base64,',
    'Dropbox Share': 'data:image/png;base64,',
    'Microsoft 365': 'data:image/png;base64,',
    'OneDrive': 'data:image/png;base64,',
    'OneDrive Share': 'data:image/png;base64,',
    'Outlook': 'data:image/png;base64,',
    'QuickBooks': 'data:image/png;base64,',
    'SharePoint': 'data:image/png;base64,',
    'SharePoint Request': 'data:image/png;base64,',
    'Crimson Paw': 'data:image/png;base64,',
    'Teams': 'data:image/svg+xml;base64,',
    'Microsoft Teams': 'data:image/svg+xml;base64,',
    'Teams Meeting': 'data:image/svg+xml;base64,',
    'Voicemail': 'data:image/svg+xml;base64,',
    'Cloud Voicemail': 'data:image/svg+xml;base64,',
    'Microsoft 365 Voicemail': 'data:image/svg+xml;base64,',
}

DEFAULT_BG_BLUEPRINT_B64 = 'data:image/jpeg;base64,'

def get_logo_data_url(brand):
    b_lower = brand.lower()
    for k, v in BRAND_LOGOS_B64.items():
        if k.lower() == b_lower or k.lower() in b_lower:
            return v
    return BRAND_LOGOS_B64.get('Microsoft 365', '')

def get_logo_html(brand, max_height=48, max_width=140, extra_style=''):
    url = get_logo_data_url(brand)
    if not url:
        return ''
    style = f'max-height:{max_height}px; max-width:{max_width}px; object-fit:contain; display:block; margin:0 auto; {extra_style}'
    return f'<img src="{url}" alt="{brand}" style="{style}">'
